#include <vector>
#include <complex>
#include <algorithm>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort.
    // Each phase performs independent compare-exchange operations on disjoint pairs,
    // so it is correct for any OpenMP thread count.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2; // even phase: (0,1), (2,3), ...; odd phase: (1,2), (3,4), ...
        if (start + 1 >= n) continue;

        #pragma omp parallel for default(none) shared(x, n, start)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i < static_cast<std::ptrdiff_t>(n - 1);
             i += 2) {
            const double mag1 = std::norm(x[static_cast<std::size_t>(i)]);
            const double mag2 = std::norm(x[static_cast<std::size_t>(i + 1)]);
            if (mag1 > mag2) {
                std::swap(x[static_cast<std::size_t>(i)],
                          x[static_cast<std::size_t>(i + 1)]);
            }
        }
        // Implicit barrier at the end of omp parallel for ensures phase completion.
    }
}
